using System;
using System.IO;
using Blockparty.Activities;
using Blockparty.Automation;
using Blockparty.Contracts;
using Blockparty.Persistence;
using Blockparty.Simulation;
using Blockparty.UI;
public class M1Regressions {
 const StateWriter Core=StateWriter.SimCore;
 const StateWriter Exec=StateWriter.ActivityExecutor;
 static int failures;
 static TierContext Hidden=new TierContext(new ResidentId[0],null,null,new ResidentId[0][]);
 class Scene:ISceneContent {public int Calls; public void RegisterObjects(ActivityExecutor e){Calls++;e.RegisterObject((ObjectId)9L,new[]{new ApproachPose(0f,0f,0f)});}}
 class F {
  public WorldState W;public AppearanceStore A;public Clock C;public CommandArbitrator Q;public ActivityExecutor E;public Accounts Ac;public Food Food;public PopulationScheduler S;public ResidentId R;public Scene Scene=new Scene();
  public F(){W=ResidentFactory.CreateNewGame(27L,42L,new[]{"A","B","C","D","E","F","G","H"},out A);C=new Clock(W);Q=new CommandArbitrator(W,C);E=new ActivityExecutor(W,Q,C);Ac=new Accounts(W);Food=new Food(W,Q,E,Ac);R=W.ResidentsSnapshot()[0].Id; foreach(var r in W.ResidentsSnapshot()){W.SetMoney(Core,r.Id,50L);for(int n=0;n<StateSchema.NeedCount;n++)W.SetNeed(Core,r.Id,(Need)n,40f);}while((long)W.AllocateObject(Core)<9L){} Scene.RegisterObjects(E);E.SetResidentPosition(R,new ApproachPose(0f,0f,0f));foreach(var home in W.ExportSnapshot().Homes)Food.SetHomeStock(Core,home.Id,8,0);S=new PopulationScheduler(W,C,Q,E,new Autonomy(W,Q));}
  public ResidentRecord Row(){ResidentRecord r;W.TryGetResident(R,out r);return r;}
  public CommandEnvelope Cmd(string code){return new CommandEnvelope(W.AllocateCommand(Core),W.Epoch,W.GameSeconds,CommandSource.PlayerHuman,Q.CurrentStamp(R).Sequence+1u,CommandKind.DirectActivity,R,new ActivityId(code),9L,new CommandParameters.Direct(QueueMode.Immediate));}
 }
 static void Check(bool pass,string id,string actual){Console.WriteLine((pass?"PASS ":"FAIL ")+id+" "+actual);if(!pass)failures++;}
 static void Transfer(){var f=new F();long before=f.Row().Money;string error="none";try{f.Ac.Transfer(Core,f.W.AllocateAction(Core),AccountRef.Personal(f.R),AccountRef.Personal((ResidentId)99999L),10L);}catch(Exception e){error=e.GetType().Name;}Check(f.Row().Money==before,"ACCOUNTS-ATOMIC","before="+before+" after="+f.Row().Money+" ledger="+f.Ac.Ledger.Count+" exception="+error);}
 static void Overflow(){var f=new F();var to=f.W.ResidentsSnapshot()[1].Id;f.W.SetMoney(Core,to,long.MaxValue);string error="none";try{f.Ac.Transfer(Core,f.W.AllocateAction(Core),AccountRef.Personal(f.R),AccountRef.Personal(to),10L);}catch(Exception e){error=e.GetType().Name;}Check(f.Row().Money==50L,"ACCOUNTS-OVERFLOW-ATOMIC","payer="+f.Row().Money+" ledger="+f.Ac.Ledger.Count+" exception="+error);}
 static void Title(string dir){var scene=new Scene();var t=new TitleFlow(dir,scene);t.Activate(TitleAction.NewGame);t.PrepareNewGame(27L,42L,new[]{"A","B","C","D","E","F","G","H"});t.BeginPlay();Check(t.Game.Accounts!=null&&t.Game.Food!=null&&scene.Calls>0,"TITLE-FULL-STACK","accounts="+(t.Game.Accounts!=null)+" food="+(t.Game.Food!=null)+" sceneCalls="+scene.Calls);}
 static void Chunking(){var a=new F();var b=new F();a.Food.Submit(a.Cmd("ACT-FOOD-04"));b.Food.Submit(b.Cmd("ACT-FOOD-04"));var aa=a.Q.GetCurrent(a.R);if(aa==null)aa=a.Q.GetPending(a.R)[0];var ab=b.Q.GetCurrent(b.R);if(ab==null)ab=b.Q.GetPending(b.R)[0];a.S.AdvanceRealSeconds(Core,16.0,Hidden);for(int n=0;n<160;n++)b.S.AdvanceRealSeconds(Core,0.1,Hidden);var ea=a.E.GetExecution(aa.Action);var eb=b.E.GetExecution(ab.Action);Check(ea.IsTerminal==eb.IsTerminal,"TIERS-FRAME-CHUNK","batched="+ea.Stage+"/"+ea.Outcome+" split="+eb.Stage+"/"+eb.Outcome+" times="+a.W.GameSeconds+","+b.W.GameSeconds);}
 static void DoubleReward(){var f=new F();var submit=f.Food.Submit(f.Cmd("ACT-FOOD-04"));var a=f.Q.GetCurrent(f.R);if(a==null)a=f.Q.GetPending(f.R)[0];for(int n=0;n<900;n++){f.S.AdvanceRealSeconds(Core,0.1,Hidden);f.Food.Tick(Exec);var ex=f.E.GetExecution(a.Action);if(ex!=null&&ex.IsTerminal){float expected=40f-4f*(float)f.W.GameSeconds/3600f+35f;Check(ex.Outcome==TerminalOutcome.Completed&&Math.Abs(f.Row().GetNeed(Need.Hunger)-expected)<0.01,"TIERS-FOOD-ONCE","outcome="+ex.Outcome+" hunger="+f.Row().GetNeed(Need.Hunger)+" expected="+expected+" seconds="+f.W.GameSeconds+" money="+f.Row().Money+" ledger="+f.Ac.Ledger.Count);return;}}Check(false,"TIERS-FOOD-ONCE","no terminal");}
 static void Memory(){var f=new F();var ids=f.W.ResidentsSnapshot();var rel=new Relationships(f.W);var evt=rel.Complete(Core,new ActivityId("ACT-REL-04"),ids[0].Id,ids[1].Id,0.5,0.5,0.5,0.5);f.W.SetGameSeconds(Core,6L);var chat=rel.Complete(Core,new ActivityId("ACT-REL-01"),ids[0].Id,ids[2].Id);var forged=rel.Remember(Core,ids[3].Id,evt.Event,chat.Event);Check(!forged.Applied,"RELATION-CHAT-EDGE","unrelated listener applied="+forged.Applied+" reason="+forged.Reason);}
 static PlayerObservation Obs(F f){var r=f.Row();var needs=new float[StateSchema.NeedCount];for(int i=0;i<needs.Length;i++)needs[i]=r.GetNeed((Need)i);return new PlayerObservation(f.R,f.Q.CurrentStamp(f.R),f.W.GameSeconds,Array.AsReadOnly(needs),Array.AsReadOnly(new[]{new AvailableAction(new ActivityId("ACT-FOOD-04"),9L)}));}
 static void BotIds(){var f=new F();f.Q.EnableAutomation();var b1=new RulePlayer(f.Q);var b2=new RulePlayer(f.Q);var r1=b1.Apply(b1.Decide(Obs(f)));var r2=b2.Apply(b2.Decide(Obs(f)));var rows=f.Q.GetPending(f.R);var chosen=rows[1].Action;var cancelled=new ResidentPanel(f.W,f.Q).Cancel(f.R,chosen);bool remains=false;foreach(var a in f.Q.GetPending(f.R))remains|=a.Action==chosen;Check(r1.Accepted&&r2.Accepted&&cancelled.Accepted&&!remains,"BOT-COMMAND-ID-COLLISION","ids="+(long)rows[0].Command+","+(long)rows[1].Command+" cancelled_selected_still_queued="+remains);}
 static void SharedOverflow(){var f=new F();var home=f.Row().Household;f.Ac.SetSharedBalance(Core,home,long.MaxValue);var result=f.Ac.Transfer(Core,f.W.AllocateAction(Core),AccountRef.Personal(f.R),AccountRef.Shared(home),1L);Check(!result.Accepted&&f.Row().Money==50L&&f.Ac.Balance(AccountRef.Shared(home))==long.MaxValue,"ACCOUNTS-SHARED-OVERFLOW","accepted="+result.Accepted+" payer="+f.Row().Money+" shared="+f.Ac.Balance(AccountRef.Shared(home)));}
 static void ForgedSave(string dir){var f=new F();var action=f.W.AllocateAction(Core);f.Ac.Transfer(Core,action,AccountRef.Personal(f.R),AccountRef.Expense("test"),10L);SaveV1.SaveGame(new GameStack(f.W,f.C,f.Q,f.E,f.A,f.Ac,f.Food),dir);var path=Path.Combine(dir,"save.json");var doc=SaveV1.ParseDocument(File.ReadAllBytes(path));var payload=doc.GetObject("payload","root");payload.GetObject("accounts","payload").Set("applied",new JsonArray());File.WriteAllBytes(path,SaveV1.AssembleDocument(payload,SaveFormat.SchemaVersion,f.W.WorldId,(uint)f.W.Epoch,f.W.GameSeconds));var loaded=SaveV1.LoadGame(dir,f.Scene);bool replay=false;long money=-1;if(loaded.Ok){replay=loaded.Game.Accounts.Transfer(Core,action,AccountRef.Personal(f.R),AccountRef.Expense("test"),10L).Accepted;ResidentRecord r;loaded.Game.World.TryGetResident(f.R,out r);money=r.Money;}Check(!loaded.Ok,"SAVE-ACCOUNT-APPLIED-INVARIANT","forged_save_loaded="+loaded.Ok+" payment_replayed="+replay+" money="+money);}
 static void InvalidLedger(){var f=new F();f.Ac.Transfer(Core,f.W.AllocateAction(Core),AccountRef.Personal(f.R),AccountRef.Expense("test"),10L);var snap=f.Ac.Export();snap.Ledger[0].Amount=-10L;snap.Ledger[0].Source.Kind="expense";snap.Ledger[0].Source.Name="impossible-source";bool rejected=false;try{f.Ac.Import(Core,snap);}catch(ArgumentException){rejected=true;}Check(rejected,"ACCOUNTS-INVALID-LEDGER","rejected="+rejected+" ledger_amount="+f.Ac.Export().Ledger[0].Amount+" source="+f.Ac.Export().Ledger[0].Source.Kind);}
 static void RetroMemory(){var f=new F();var ids=f.W.ResidentsSnapshot();var rel=new Relationships(f.W);var evt=rel.Complete(Core,new ActivityId("ACT-REL-04"),ids[0].Id,ids[1].Id,0.5,0.5,0.5,0.5);f.W.SetGameSeconds(Core,6L);var prior=rel.Complete(Core,new ActivityId("ACT-REL-01"),ids[2].Id,ids[3].Id);f.W.SetGameSeconds(Core,12L);rel.Complete(Core,new ActivityId("ACT-REL-01"),ids[0].Id,ids[2].Id);var retro=rel.Remember(Core,ids[3].Id,evt.Event,prior.Event);Check(!retro.Applied,"RELATION-RETROACTIVE-CHAT","applied="+retro.Applied+" source_t=0 prior_chat_t=6 speaker_learned_t=12");}
 static void RelationRng(string dir){var f=new F();var ids=f.W.ResidentsSnapshot();var rel=new Relationships(f.W);rel.Complete(Core,new ActivityId("ACT-REL-04"),ids[0].Id,ids[1].Id);SaveV1.SaveGame(new GameStack(f.W,f.C,f.Q,f.E,f.A,f.Ac,f.Food),dir);var loaded=SaveV1.LoadGame(dir,f.Scene);var resumed=new Relationships(loaded.Game.World);var expected=rel.Complete(Core,new ActivityId("ACT-REL-04"),ids[0].Id,ids[1].Id);var actual=resumed.Complete(Core,new ActivityId("ACT-REL-04"),ids[0].Id,ids[1].Id);Check(expected.Draws[0].Draw==actual.Draws[0].Draw&&expected.Draws[0].Sequence==actual.Draws[0].Sequence,"RELATION-RNG-CONTINUITY","uninterrupted="+expected.Draws[0].Draw+" seq="+expected.Draws[0].Sequence+" reload="+actual.Draws[0].Draw+" seq="+actual.Draws[0].Sequence);}
 static void InvalidWriter(){var a=new F();var b=new F();var ra=new Relationships(a.W);var rb=new Relationships(b.W);var ids=a.W.ResidentsSnapshot();bool refused=false;try{ra.Complete((StateWriter)99,new ActivityId("ACT-REL-03"),ids[0].Id,ids[1].Id);}catch(ArgumentException){refused=true;}var actual=ra.Complete(Core,new ActivityId("ACT-REL-04"),ids[0].Id,ids[1].Id);var expected=rb.Complete(Core,new ActivityId("ACT-REL-04"),ids[0].Id,ids[1].Id);Check(refused&&expected.Draws[0].Draw==actual.Draws[0].Draw&&expected.Draws[0].Sequence==actual.Draws[0].Sequence,"RELATION-INVALID-WRITER","refused="+refused+" expected_draw="+expected.Draws[0].Draw+" actual_draw="+actual.Draws[0].Draw+" expected_seq="+expected.Draws[0].Sequence+" actual_seq="+actual.Draws[0].Sequence);}
 static void NavCollision(){var f=new F();var rows=f.W.ResidentsSnapshot();var walker=rows[1].Id;f.E.RegisterObject((ObjectId)(long)f.R,new[]{new ApproachPose(50f,0f,0f)});f.E.SetResidentPosition(walker,new ApproachPose(0f,0f,0f));var nav=new WorldNavigation(f.W,f.Q,f.E);nav.SelectResident(f.R);var result=nav.TravelTo(walker,(long)f.R,QueueMode.Immediate);for(int n=0;n<600;n++){f.C.AdvanceRealSeconds(Core,0.1);f.E.Tick(Exec);}var actual=f.E.GetResidentPosition(walker);var intended=f.E.GetResidentPosition(f.R);Check(result.Accepted&&Math.Abs(actual.X-intended.X)<0.001,"NAV-TARGET-ID-COLLISION","accepted="+result.Accepted+" target_resident_x="+intended.X+" actual_x="+actual.X+" colliding_object_x=50");}
 class CollisionScene:ISceneContent {public void RegisterObjects(ActivityExecutor e){e.RegisterObject((ObjectId)1L,new[]{new ApproachPose(50f,0f,0f)});e.RegisterObject((ObjectId)9L,new[]{new ApproachPose(0f,0f,0f)});}}
 static void TravelSave(string dir){
  foreach(var kind in new[]{TravelTargetKind.Resident,TravelTargetKind.Object}){
   var f=new F();var walker=f.W.ResidentsSnapshot()[1].Id;f.E.RegisterObject((ObjectId)(long)f.R,new[]{new ApproachPose(50f,0f,0f)});f.E.SetResidentPosition(f.R,new ApproachPose(12f,0f,0f));
   var nav=new WorldNavigation(f.W,f.Q,f.E);var submitted=nav.TravelTo(walker,(long)f.R,QueueMode.Immediate,kind);f.E.Tick(Exec);
   string path=Path.Combine(dir,kind.ToString());var saved=SaveV1.SaveGame(new GameStack(f.W,f.C,f.Q,f.E,f.A,f.Ac,f.Food),path);var loaded=SaveV1.LoadGame(path,new CollisionScene());
   var g=loaded.Game;var entry=g.Arbitrator.GetCurrent(walker);
   bool retained=submitted.Accepted&&saved.Ok&&loaded.Ok&&entry!=null&&entry.TargetKind==kind;
   for(int i=0;i<600;i++){g.Clock.AdvanceRealSeconds(Core,.1);g.Executor.Tick(Exec);}
   Check(retained&&Math.Abs(g.Executor.GetResidentPosition(walker).X-(kind==TravelTargetKind.Resident?12f:50f))<.06f,"NAV-TARGET-KIND-SAVE-"+kind,"retained="+retained+" x="+g.Executor.GetResidentPosition(walker).X);
  }
 }
 static void NavRefusal(){var f=new F();for(int n=0;n<8;n++){var cmd=new CommandEnvelope(f.W.AllocateCommand(Core),f.W.Epoch,f.W.GameSeconds,CommandSource.PlayerHuman,f.Q.CurrentStamp(f.R).Sequence+1u,CommandKind.DirectActivity,f.R,new ActivityId("ACT-FOOD-04"),9L,new CommandParameters.Direct(QueueMode.Append));f.Q.Submit(cmd);}int before=f.W.ComputeStateHash();var result=new WorldNavigation(f.W,f.Q,f.E).TravelTo(f.R,9L,QueueMode.Append);Check(!result.Accepted&&f.W.ComputeStateHash()==before,"NAV-REFUSED-MUTATION","accepted="+result.Accepted+" reason="+result.Reason+" before_hash="+before+" after_hash="+f.W.ComputeStateHash());}
 static ExecutionRecord RunFood(F f,string code){var r=f.Food.Submit(f.Cmd(code));if(!r.Accepted)throw new Exception("fixture food refused "+r.Reason);var a=f.Q.GetCurrent(f.R);if(a==null)a=f.Q.GetPending(f.R)[0];for(int n=0;n<1000;n++){f.C.AdvanceRealSeconds(Core,0.1);f.Food.Tick(Exec);var e=f.E.GetExecution(a.Action);if(e!=null&&e.IsTerminal)return e;}throw new Exception("fixture food timeout");}
 static void FoodPurchase(){var f=new F();f.W.SetMoney(Core,f.R,1000L);f.Food.SetHomeStock(Core,f.Row().Home,0,0);RunFood(f,"ACT-FOOD-03");Check(f.Row().Money==900L&&f.Food.GroceryUnits(f.Row().Home)==4,"FOOD-DEFAULT-PURCHASE","money="+f.Row().Money+" groceries="+f.Food.GroceryUnits(f.Row().Home));var big=new F();big.W.SetMoney(Core,big.R,25L*(int.MaxValue+1L));big.Food.SetHomeStock(Core,big.Row().Home,0,0);RunFood(big,"ACT-FOOD-03");string detail=big.W.Events[big.W.Events.Count-1].Detail;Check(big.Food.GroceryUnits(big.Row().Home)==4,"FOOD-LARGE-PURCHASE","groceries="+big.Food.GroceryUnits(big.Row().Home)+" last_event="+detail);var cap=new F();cap.Food.SetHomeStock(Core,cap.Row().Home,int.MaxValue,0);RunFood(cap,"ACT-FOOD-03");Check(cap.Food.GroceryUnits(cap.Row().Home)>=0,"FOOD-STOCK-OVERFLOW","groceries="+cap.Food.GroceryUnits(cap.Row().Home)+" money="+cap.Row().Money);}
 static void ChildPayer(){
  var f=new F();f.W.SetStage(Core,f.R,LifeStage.Child,0f);var cmd=f.Cmd("ACT-FOOD-04");int before=f.W.ComputeStateHash();var result=f.Food.Submit(cmd);
  Check(!result.Accepted&&result.Reason==RejectReason.StageIneligible&&f.W.ComputeStateHash()==before&&f.Q.GetCurrent(f.R)==null&&f.Q.GetPending(f.R).Length==0&&f.Ac.Ledger.Count==0,"FOOD-CHILD-PAYER","accepted="+result.Accepted+" reason="+result.Reason+" unchanged="+(f.W.ComputeStateHash()==before)+" child_money="+f.Row().Money);
  foreach(var stage in new[]{LifeStage.Teen,LifeStage.Adult}){var payer=new F();payer.W.SetStage(Core,payer.R,stage,0f);RunFood(payer,"ACT-FOOD-04");Check(payer.Row().Money==32L&&payer.Ac.Ledger.Count==1,"FOOD-OWN-PAYER-"+stage,"money="+payer.Row().Money+" ledger="+payer.Ac.Ledger.Count);}
 }
 static void CookingCap(){var f=new F();f.W.AddSkillPoints(Core,f.R,"Cooking",2090);RunFood(f,"ACT-FOOD-01");int level=-1;foreach(var k in f.Row().Skills)if(k.SkillId=="Cooking")level=k.Level;Check(level<=5,"FOOD-COOKING-CAP","uncertified_level="+level);}
 static void FoodImport(string dir){var f=new F();f.Food.Submit(f.Cmd("ACT-FOOD-04"));var snap=f.Food.Export();snap.Tracked[0].Resident=99999L;bool refused=false;try{f.Food.Import(Core,snap);}catch(ArgumentException){refused=true;}bool loadedOk=false;string error="none";if(!refused){SaveV1.SaveGame(new GameStack(f.W,f.C,f.Q,f.E,f.A,f.Ac,f.Food),dir);var loaded=SaveV1.LoadGame(dir,f.Scene);loadedOk=loaded.Ok;if(loaded.Ok){loaded.Game.Clock.AdvanceRealSeconds(Core,0.1);try{loaded.Game.Food.Tick(Exec);}catch(Exception e){error=e.GetType().Name;}}}Check(refused,"FOOD-INVALID-SAVE-REFERENCE","import_refused="+refused+" load="+loadedOk+" tick_exception="+error);}
 static void FoodWriter(){var f=new F();f.W.SetMoney(Core,f.R,0);f.Q.Submit(f.Cmd("ACT-FOOD-04"));int before=f.W.ComputeStateHash();bool refused=false;try{f.Food.Tick((StateWriter)99);}catch(ArgumentException){refused=true;}Check(refused&&before==f.W.ComputeStateHash(),"FOOD-INVALID-WRITER","refused="+refused+" before="+before+" after="+f.W.ComputeStateHash()+" queue_after="+f.Q.GetPending(f.R).Length);}
 static void FoodDeath(){var f=new F();f.Food.Submit(f.Cmd("ACT-FOOD-04"));f.W.SetMoney(Core,f.R,0);f.W.SetAlive(Core,f.R,false);string error="none";try{f.Food.Tick(Exec);}catch(Exception e){error=e.GetType().Name+":"+e.Message;}Check(error=="none","FOOD-DEAD-RESOURCE-CLEANUP","error="+error);}
 static void FoodReservation(){var f=new F();f.Food.SetHomeStock(Core,f.Row().Home,1,0);f.Food.Submit(f.Cmd("ACT-FOOD-01"));var a=f.Q.GetCurrent(f.R);if(a==null)a=f.Q.GetPending(f.R)[0];for(int n=0;n<10&&f.Food.Export().Tracked[0].ReservedGroceries==0;n++){f.C.AdvanceRealSeconds(Core,0.1);f.Food.Tick(Exec);}int reserved=f.Food.Export().Tracked[0].ReservedGroceries;new ResidentPanel(f.W,f.Q).Cancel(f.R,a.Action);bool queued=f.Q.EnqueueAutonomous(f.R,new ActivityId("ACT-FOOD-01"),9L);f.C.AdvanceRealSeconds(Core,0.1);f.Food.Tick(Exec);bool remains=f.Q.GetCurrent(f.R)!=null||f.Q.GetPending(f.R).Length>0;Check(queued&&remains,"FOOD-RETRY-RESERVATION","old_reserved="+reserved+" replacement_enqueued="+queued+" replacement_remains="+remains+" groceries="+f.Food.GroceryUnits(f.Row().Home));}
 class EmptyScene:ISceneContent{public void RegisterObjects(ActivityExecutor e){}}
 static TitleFlow NewTitle(string dir){var t=new TitleFlow(dir,new EmptyScene());t.Activate(TitleAction.NewGame);t.PrepareNewGame(27L,42L,new[]{"A","B","C","D","E","F","G","H"});t.BeginPlay();return t;}
 static void TitleTransitions(string dir){var t=NewTitle(dir);t.Activate(TitleAction.Pause);t.Activate(TitleAction.Save);t.Activate(TitleAction.ReturnToTitle);var c=t.Activate(TitleAction.Continue);long before=t.Game.World.GameSeconds;t.Game.Clock.AdvanceRealSeconds(Core,1);Check(c.Ok&&t.Game.World.GameSeconds>before,"TITLE-CONTINUE-PAUSED","screen="+t.Screen+" paused="+t.Game.Clock.Paused+" before="+before+" after="+t.Game.World.GameSeconds);t.Activate(TitleAction.Pause);t.Activate(TitleAction.ReturnToTitle);var old=t.Game;t.Activate(TitleAction.NewGame);var began=t.BeginPlay();Check(!began.Ok,"TITLE-OLD-GAME-REUSED","begin_without_prepare="+began.Ok+" same_game="+Object.ReferenceEquals(old,t.Game)+" paused="+t.Game.Clock.Paused);var loader=new TitleFlow(dir,new EmptyScene());loader.Activate(TitleAction.Load);var l=loader.LoadSavedGame();long x=loader.Game.World.GameSeconds;loader.Game.Clock.AdvanceRealSeconds(Core,1);Check(l.Ok&&loader.Game.World.GameSeconds>x,"TITLE-LOAD-PAUSED","paused="+loader.Game.Clock.Paused+" time="+loader.Game.World.GameSeconds);}
 static void BadSettings(string dir){Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"settings.json"),"{}");string error="none";try{new TitleFlow(dir,new EmptyScene());}catch(Exception e){error=e.GetType().Name;}Check(error=="none","TITLE-CORRUPT-SETTINGS","exception="+error);var t=new TitleFlow(dir+"-finite",new EmptyScene());t.Activate(TitleAction.Settings);error="none";bool ok=false;try{ok=t.ApplySettings(new SettingsRecord(1,float.NaN,1f,false)).Ok;}catch(Exception e){error=e.GetType().Name;}Check(error=="none"&&!ok,"TITLE-NONFINITE-SETTINGS","exception="+error+" accepted="+ok);}
 static void Saturation(){var f=new F();f.W.SetNeed(Core,f.R,Need.Hunger,80f);f.Food.Submit(f.Cmd("ACT-FOOD-04"));var a=f.Q.GetCurrent(f.R);if(a==null)a=f.Q.GetPending(f.R)[0];for(int n=0;n<900;n++){f.S.AdvanceRealSeconds(Core,0.1,Hidden);var e=f.E.GetExecution(a.Action);if(e!=null&&e.IsTerminal)break;}float before=f.Row().GetNeed(Need.Hunger);f.S.AdvanceRealSeconds(Core,0.1,Hidden);Check(before==100f&&f.Row().GetNeed(Need.Hunger)<100f,"TIERS-CLAMP-ANCHOR","completed_hunger="+before+" next_tick="+f.Row().GetNeed(Need.Hunger));}
 static void SharedTier(){var f=new F();var ids=f.W.ResidentsSnapshot();f.Food.Submit(f.Cmd("ACT-FOOD-04"));f.S.Recompute(new TierContext(new ResidentId[0],null,null,new[]{new[]{ids[0].Id,ids[1].Id}}));Check(f.S.GetTier(ids[1].Id)==SimulationTier.Detailed,"TIERS-SHARED-PLAYER-SEED","player="+f.S.GetTier(ids[0].Id)+" partner="+f.S.GetTier(ids[1].Id));}
 static void LastTick(string dir){var f=new F();f.Food.Submit(f.Cmd("ACT-FOOD-04"));for(int n=0;n<150;n++)f.S.AdvanceRealSeconds(Core,0.1,Hidden);SaveV1.SaveGame(new GameStack(f.W,f.C,f.Q,f.E,f.A,f.Ac,f.Food),dir);var loaded=SaveV1.LoadGame(dir,f.Scene);var g=loaded.Game;var scheduler=new PopulationScheduler(g.World,g.Clock,g.Arbitrator,g.Executor,new Autonomy(g.World,g.Arbitrator));f.S.AdvanceRealSeconds(Core,0.1,Hidden);scheduler.AdvanceRealSeconds(Core,0.1,Hidden);ResidentRecord r;g.World.TryGetResident(f.R,out r);Check(Math.Abs(f.Row().GetNeed(Need.Hunger)-r.GetNeed(Need.Hunger))<0.001,"TIERS-RESTORE-FIRST-COMPLETION","uninterrupted="+f.Row().GetNeed(Need.Hunger)+" resumed="+r.GetNeed(Need.Hunger));}
 static void IdleContinuity(string dir){var f=new F();for(int n=0;n<9;n++)f.S.AdvanceRealSeconds(Core,0.1,Hidden);SaveV1.SaveGame(new GameStack(f.W,f.C,f.Q,f.E,f.A,f.Ac,f.Food),dir);var g=SaveV1.LoadGame(dir,f.Scene).Game;var autonomy=new Autonomy(g.World,g.Arbitrator);var scheduler=new PopulationScheduler(g.World,g.Clock,g.Arbitrator,g.Executor,autonomy);f.S.AdvanceRealSeconds(Core,0.1,Hidden);scheduler.AdvanceRealSeconds(Core,0.1,Hidden);Check(autonomy.Decisions.Count>0,"TIERS-IDLE-CONTINUITY","resumed_time="+g.World.GameSeconds+" resumed_decisions="+autonomy.Decisions.Count);}
 static void SaveNegative(string dir){var f=new F();var stack=new GameStack(f.W,f.C,f.Q,f.E,f.A,f.Ac,f.Food);var saved=SaveV1.SaveGame(stack,dir);var path=Path.Combine(dir,"save.json");var good=File.ReadAllBytes(path);int hash=f.W.ComputeStateHash();File.WriteAllText(path,"{broken");var bad=File.ReadAllBytes(path);var loaded=SaveV1.LoadGame(dir,f.Scene);Check(saved.Ok&&!loaded.Ok&&f.W.ComputeStateHash()==hash&&Convert.ToBase64String(bad)==Convert.ToBase64String(File.ReadAllBytes(path)),"SAVE-CORRUPT-NEGATIVE","saved="+saved.Ok+" load="+loaded.Ok+" notice="+loaded.Notice);File.WriteAllBytes(path,good);var valid=SaveV1.LoadGame(dir,f.Scene);Check(valid.Ok&&valid.Game.Accounts!=null&&valid.Game.Food!=null,"SAVE-FULL-STACK-ROUNDTRIP","ok="+valid.Ok);}
 public static int Run(string package) {
  failures=0;
  string root=Path.Combine(Path.GetTempPath(),"blockparty-m1-repair-"+Guid.NewGuid().ToString("N"));
  Directory.CreateDirectory(root);
  try {
   switch(package) {
    case "ECONOMY": Transfer();Overflow();SharedOverflow();InvalidLedger();break;
    case "BOT": BotIds();break;
    case "RELATION": Memory();RetroMemory();InvalidWriter();RelationRng(Path.Combine(root,"rng"));break;
    case "TIERS": Chunking();DoubleReward();Saturation();SharedTier();LastTick(Path.Combine(root,"last"));IdleContinuity(Path.Combine(root,"idle"));break;
    case "FOOD": FoodPurchase();CookingCap();FoodImport(Path.Combine(root,"import"));FoodWriter();FoodDeath();FoodReservation();ChildPayer();break;
    case "UI-TITLE": Title(Path.Combine(root,"title"));TitleTransitions(Path.Combine(root,"transitions"));BadSettings(Path.Combine(root,"settings"));break;
    case "UI-NAV": NavCollision();NavRefusal();break;
    case "SAVE": TravelSave(Path.Combine(root,"travel"));ForgedSave(Path.Combine(root,"forged"));SaveNegative(Path.Combine(root,"save"));break;
   }
   return failures;
  } finally {Directory.Delete(root,true);}
 }
}
